function draw(input){const{svg,width,height,params}=input;
const C={ink:'#263e47',muted:'#64777e',grid:'#d9e1e2',blue:'#287b91',rust:'#ad522f'};
function el(id,tag,a,text){let e=svg.querySelector('[data-draw-id="'+id+'"]');if(!e){e=svg.ownerDocument.createElementNS('http://www.w3.org/2000/svg',tag);e.setAttribute('data-draw-id',id);svg.appendChild(e);}for(const[k,v]of Object.entries(a))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e;}
function txt(id,x,y,s,color=C.ink,size=14,anchor='start'){return el(id,'text',{x,y,fill:color,'font-size':size,'font-family':'system-ui,sans-serif','text-anchor':anchor},s);}
function ln(id,x1,y1,x2,y2,color=C.grid,dash=''){return el(id,'line',{x1,y1,x2,y2,stroke:color,'stroke-width':1,'stroke-dasharray':dash});}
function path(id,d,color,dash=''){return el(id,'path',{d,fill:'none',stroke:color,'stroke-width':2.5,'stroke-dasharray':dash,'stroke-linejoin':'round'});}
function dot(id,x,y,color,r=4){return el(id,'circle',{cx:x,cy:y,r,fill:color,stroke:'#faf9f5','stroke-width':2});}
const mobile=width<500;const L=48,R=width-16;

const B=Number(params.batch),D=4096,F=11008,P=989e12,M=3.35e12;
const ops=2*B*D*F,bytes=2*(B*D+D*F+B*F),I=ops/bytes,cross=P/M;
const critical=cross/(1-cross*(1/D+1/F));const compute=ops/P*1e6,transfer=bytes/M*1e6;
txt('condition',12,20,'BF16 · D=4096 · F=11008',C.muted,13);
ln('legend-exact',12,42,31,42,C.blue);txt('legend-exact-t',37,47,'精确 I',C.blue,13);
ln('legend-approx',112,42,135,42,C.muted,'5 4');txt('legend-approx-t',141,47,'近似 I=B',C.muted,13);
txt('ytitle',L,74,'强度 · FLOP/Byte',C.muted,12);
const plotR=mobile?R:width*.60;const top=86,bottom=mobile?252:290;const x=b=>L+(plotR-L)*b/1024,y=i=>bottom-(bottom-top)*i/1100;
for(const v of [0,500,1000]){ln('yg'+v,L,y(v),plotR,y(v));txt('yt'+v,L-8,y(v)+4,''+v,C.muted,12,'end');}
const ticks=mobile?[0,512,1024]:[0,256,512,768,1024];
for(const v of ticks){ln('xt'+v,x(v),bottom,x(v),bottom+5,C.muted);txt('xl'+v,x(v),bottom+20,''+v,C.muted,12,v===0?'start':v===1024?'end':'middle');}
txt('xtitle',plotR,bottom+39,'批量 B',C.muted,12,'end');
ln('boundary',L,y(cross),plotR,y(cross),C.rust,'3 4');txt('boundary-label',plotR,y(cross)-8,'拐点 295',C.rust,12,'end');
let d='';for(let i=0;i<=128;i++){const b=i*8;d+=(i?'L':'M')+x(b)+','+y(b/(1+b*(1/D+1/F)));}path('exact',d,C.blue);
path('approx','M'+x(0)+','+y(0)+'L'+x(1024)+','+y(1024),C.muted,'6 5');
ln('selected',x(B),bottom,x(B),y(I),C.blue,'2 4');dot('selected-dot',x(B),y(I),C.blue,5);
const side=mobile?12:plotR+38;
if(!mobile)txt('time-title',side,74,'理想时间下界 · μs',C.muted,14);
txt('current',side,mobile?313:118,'B='+B+'  →  I='+I.toFixed(1),C.blue,16);
txt('status',mobile?R:side,mobile?313:148,I<cross?'搬运较慢':'计算较慢',C.rust,13,mobile?'end':'start');
const barL=mobile?60:side+52,barR=R-64,bw=barR-barL;
for(const [key,label,val,color,yy] of [['compute','计算',compute,C.blue,mobile?344:199],['memory','搬运',transfer,C.rust,mobile?383:249]]){
txt(key+'label',side,yy+5,label,C.muted,13);ln(key+'track',barL,yy,barR,yy);el(key+'bar','rect',{x:barL,y:yy-4,width:Math.max(.4,bw*val/100),height:8,rx:2,fill:color});txt(key+'value',R,yy+5,val.toFixed(2)+' μs',color,12,'end');}
txt('time-scale',barL,mobile?412:286,'两条共用 0–100 μs 刻度',C.muted,12);
txt('critical',12,mobile?440:351,'精确分界：B≈'+critical.toFixed(0)+'，并非 B=295',C.ink,13);
return{B,D,F,flops:ops,bytes,intensity:I,crossover:cross,criticalBatch:critical,computeUs:compute,transferUs:transfer,idealUs:Math.max(compute,transfer),convention:'峰值速率、一次理想读写、计算搬运完全重叠；非实测'};
}

